// Actual SQLite transactions; packet custody/authentication observations below
// are synthetic host ports. Native parsing and installed IPC are separate tests.
#define main retained_held_file_fixture_main
#include "file_storage_tests.cpp"
#undef main
#include "sfx/application/ftn_work.hpp"
#include <sodium.h>
namespace {
app::FtnDigest hash(std::string_view s){app::FtnDigest d{};check(crypto_hash_sha256(d.data(),reinterpret_cast<const unsigned char*>(s.data()),s.size())==0,"fixture SHA256");return d;}
struct HeldFixture {app::FtnImportRequest request;app::FtnHeldMessage held;};
HeldFixture held_fixture(storage::SqliteStorage& db,const app::FtnConfiguration& c,unsigned number,bool direct=false){
    const app::MessageConfigurationActor owner{true,{}};HeldFixture f;auto& r=f.request;r.operation=id(100+number);r.ingress=id(200+number);r.expected_configuration_revision=c.revision;r.network="TEST";r.header.origin=*app::parse_ftn_address("2:100/2@test");r.header.destination=*app::parse_ftn_address("2:100/1@test");r.header.year=2026;r.header.month=10;r.header.day=29;
    auto& m=r.message;m.origin_net=100;m.origin_node=2;m.destination_net=100;m.destination_node=1;m.date="29 Oct 26  12:00:00";m.to="Unknown Remote To";m.from="Remote Author";m.subject="Private subject not in review";m.text="\1MSGID: 2:100/2 "+std::to_string(number)+"\r\1CHRS: CP437 2\rPRIVATE BODY NOT IN REVIEW\r";
    const auto meta=app::inspect_ftn_message(r.header,m);check(bool(meta),"fixture packet metadata");const auto material=app::ftn_message_fingerprint_material(m,*meta);r.identity=hash(material.identity);r.content=hash(material.content);const auto wire=app::encode_ftn_packet({r.header,{m}});check(bool(wire),"fixture encodes");
    app::FtnIngressReceipt receipt;receipt.id=r.ingress;receipt.session=id(300+number);receipt.identity=hash("held-custody-"+std::to_string(number));receipt.network=direct?"":"TEST";receipt.link=direct?"":"PEER";receipt.proof=direct?app::FtnIngressProof::nonsecure:app::FtnIngressProof::inbound_cram;receipt.configuration_revision=c.revision;receipt.file={"held.pkt",wire->size(),1700000000};check(bool(db.begin_ftn_ingress(owner,receipt)),"synthetic authenticated custody reserved");
    app::FilePayloadIdentity payload{0,hash(""),"123",std::to_string(1000+number)};check(db.checkpoint_ftn_ingress(owner,r.ingress,0,payload).succeeded(),"synthetic native object bound empty");payload.bytes=wire->size();payload.sha256=hash(*wire);check(db.checkpoint_ftn_ingress(owner,r.ingress,0,payload).succeeded(),"synthetic complete object checkpoint");check(db.advance_ftn_ingress(owner,r.ingress,payload.bytes,payload.bytes,payload.sha256,app::FtnIngressState::received,{}).succeeded(),"complete received receipt");check(db.claim_ftn_message(owner,r.ingress,c.revision).value==true,"one message processing owner");check(db.advance_ftn_ingress(owner,r.ingress,payload.bytes,payload.bytes,payload.sha256,app::FtnIngressState::processing,{}).succeeded(),"native processing simulation");
    auto& h=f.held;h.operation=r.operation;h.ingress=r.ingress;h.configuration_revision=c.revision;h.identity=r.identity;h.content=r.content;h.payload=payload;h.network="TEST";h.envelope_destination=app::format_ftn_address(r.header.destination);h.origin=app::format_ftn_address(meta->origin);h.destination=app::format_ftn_address(meta->destination);h.from=m.from;h.to=m.to;h.reason="ftn_recipient_unmatched";h.local_private=true;return f;
}
void held_state(storage::SqliteStorage& db,const HeldFixture& f,app::FtnIngressState state){const auto& p=f.held.payload;check(db.advance_ftn_ingress({true,{}},f.request.ingress,p.bytes,p.bytes,p.sha256,state,state==app::FtnIngressState::held?"ftn_message_import_held":"").succeeded(),"synthetic host state transition; not owner IPC");}
}
int main(int argc,char** argv){try{
    check(argc==2,"fresh held fixture root required");const std::filesystem::path root=argv[1];check(!std::filesystem::exists(root),"preserve prior held fixture");sfx::test::FakeStoragePathPolicy paths;auto s=settings(root);const auto file=s.data_directory/"SFX.DB";storage::SqliteStorage db(s,paths);check(db.start().succeeded(),"current fixed22 starts");check(db.shutdown().succeeded(),"stop before fixture actors");seed(file);check(db.start().succeeded(),"fixture writer starts");const app::MessageConfigurationActor owner{true,{}};
    auto c=*db.ftn_configuration(owner).value;app::FtnNetwork network;network.code="TEST";network.name="Synthetic Test";network.address="2:100/1@test";network.enabled=true;c.networks.push_back(network);app::FtnLink link;link.network="TEST";link.code="PEER";link.name="Synthetic Peer";link.address="2:100/2@test";link.host="127.0.0.1";link.enabled=true;link.credentials.session={1};c.links.push_back(link);c.settings.allow_direct_local_netmail=true;check(bool(db.change_ftn_configuration(owner,id(20).bytes,c)),"fixture policy");c=*db.ftn_configuration(owner).value;
    auto f=held_fixture(db,c,1);const auto rejected=db.import_ftn_message(owner,f.request);if(!rejected)std::cerr<<"Initial rejection: "<<rejected.status.operation<<" code="<<static_cast<unsigned>(rejected.status.code)<<'\n';check(!rejected&&rejected.status.operation=="FTN local recipient unmatched","unknown name is held without catchall");check(!db.record_ftn_held_message({},f.held),"caller cannot manufacture held observation");auto altered=f.held;altered.payload.file_id="555";check(!db.record_ftn_held_message(owner,altered),"different native object rejected");check(db.record_ftn_held_message(owner,f.held).succeeded(),"record native observation");check(db.ftn_ingress_receipt(owner,f.request.ingress).value->state==app::FtnIngressState::held,"observation and held latch commit together before any Bad rename");held_state(db,f,app::FtnIngressState::held);check(db.record_ftn_held_message(owner,f.held).succeeded(),"same observation reconciles");altered=f.held;altered.to="Alice";check(!db.record_ftn_held_message(owner,altered),"original remote To immutable");check(!db.held_ftn_messages({}, {},10)&&!db.held_ftn_messages(owner,{},101),"private bounded page");auto page=db.held_ftn_messages(owner,{},1);check(page&&page.value->size()==1&&page.value->front().to=="Unknown Remote To"&&page.value->front().from=="Remote Author","exact redacted held details");check(db.held_ftn_messages(owner,f.held.operation,1).value->empty(),"keyset cursor does not repeat");
    app::FtnHeldReviewQuery review_query;check(!db.ftn_held_review({},review_query)&&!db.ftn_held_recipients({},{}),"caller cannot read owner held review or active local choices");
    auto review=db.ftn_held_review(owner,review_query);if(!review)std::cerr<<review.status.operation<<'\n';check(review&&review.value->rows.size()==1&&review.value->messages.empty()&&review.value->configuration_revision==c.revision,"owner list projects exact held receipt under one current snapshot");
    check(review.value->rows.front().received_utc==scalar(file,"SELECT created_utc FROM sfx_ftn_ingress")&&review.value->rows.front().received_utc!=1700000000,"Received is actual custody time, never sender wire time");
    review_query.find="Remote Author";check(db.ftn_held_review(owner,review_query).value->rows.size()==1,"Find searches redacted original sender");review_query.find="PRIVATE BODY NOT IN REVIEW";check(db.ftn_held_review(owner,review_query).value->rows.empty(),"Find does not inspect private body");review_query.find="%";check(db.ftn_held_review(owner,review_query).value->rows.empty(),"Find treats SQL wildcard as literal");
    review_query={};review_query.after=f.request.ingress;check(db.ftn_held_review(owner,review_query).value->rows.empty(),"review keyset excludes prior original");review_query={};review_query.ingress=f.request.ingress;
    review=db.ftn_held_review(owner,review_query);check(review&&review.value->messages.size()==1&&review.value->messages.front().to=="Unknown Remote To"&&!review.value->messages.front().resolution,"detail has exact original To and no invented choice");
    auto recipients=db.ftn_held_recipients(owner,{0,"Bob"});check(recipients&&recipients.value->rows.size()==1&&recipients.value->rows.front().id==3&&recipients.value->rows.front().revision==1,"active recipient page provides exact identity and revision");check(db.ftn_held_recipients(owner,{3,"Bob"}).value->rows.empty(),"recipient keyset does not repeat");
    app::FtnRecipientResolutionRequest choice{id(500),f.held.operation,{},c.revision,2,2};check(!db.resolve_ftn_recipient(owner,choice),"stale selected account revision refused");choice.recipient_revision=1;check(!db.resolve_ftn_recipient({},choice),"caller cannot choose private recipient");const auto saved=db.resolve_ftn_recipient(owner,choice);check(bool(saved),"explicit active local account review retained");check(bool(db.resolve_ftn_recipient(owner,choice)),"lost resolution reply reconciles");auto conflict=choice;conflict.recipient=3;check(!db.resolve_ftn_recipient(owner,conflict),"same operation cannot change selected recipient");conflict.operation=id(501);check(!db.resolve_ftn_recipient(owner,conflict),"competing stale prior-decision CAS refused");
    review=db.ftn_held_review(owner,review_query);check(review&&review.value->messages.front().resolution&&review.value->messages.front().resolution->request.operation.bytes==choice.operation.bytes&&review.value->messages.front().to=="Unknown Remote To","detail separates original recipient from latest explicit decision");
    check(db.shutdown().succeeded(),"stop for account revision change fixture");{internal::SqliteConnection q(file,SQLITE_OPEN_READWRITE,std::chrono::milliseconds(100),false);q.exec("UPDATE sfx_accounts SET revision=revision+1 WHERE account_id=2","fixture account revision changes after owner review");}check(db.start().succeeded(),"reopen real ledger");held_state(db,f,app::FtnIngressState::processing);const auto stale=db.import_ftn_message(owner,f.request);check(!stale&&stale.status.operation=="FTN reviewed recipient is stale","commit rechecks account rather than following stale decision");held_state(db,f,app::FtnIngressState::held);
    conflict.previous_resolution=choice.operation;check(bool(db.resolve_ftn_recipient(owner,conflict)),"new explicit review supersedes stale account through CAS");check(bool(db.resolve_ftn_recipient(owner,choice)),"old reply reconciliation does not reactivate old choice");held_state(db,f,app::FtnIngressState::processing);const auto imported=db.import_ftn_message(owner,f.request);if(!imported)std::cerr<<imported.status.operation<<'\n';check(imported&&imported.value->message,"current resolution imports original message");const app::MessageActor bob{id(3),3,1,1},alice{id(2),2,2,1};const auto body=db.open_message(bob,imported.value->message->id);check(body&&body.value->header.to=="Unknown Remote To"&&!body.value->header.author,"remote To and author retained separately from chosen local recipient");check(!db.open_message(alice,imported.value->message->id),"no delivery to superseded recipient");check(db.import_ftn_message(owner,f.request).value->replayed,"repeat exact import does not deliver twice");conflict.operation=id(502);conflict.previous_resolution=id(501);check(!db.resolve_ftn_recipient(owner,conflict),"committed message cannot be reassigned");check(db.held_ftn_messages(owner,{},10).value->empty(),"completed constituent leaves unresolved page");
    auto direct=held_fixture(db,c,2,true);check(!db.import_ftn_message(owner,direct.request),"direct unknown recipient not caught by Sysop");check(db.record_ftn_held_message(owner,direct.held).succeeded(),"nonsecure observation keeps original receipt");held_state(db,direct,app::FtnIngressState::held);app::FtnRecipientResolutionRequest direct_choice{id(510),direct.held.operation,{},c.revision,3,1};check(bool(db.resolve_ftn_recipient(owner,direct_choice)),"explicit local recipient does not need fabricated session authentication");c.settings.allow_direct_local_netmail=false;check(bool(db.change_ftn_configuration(owner,id(21).bytes,c)),"direct admission disabled after review");c=*db.ftn_configuration(owner).value;direct.request.expected_configuration_revision=c.revision;held_state(db,direct,app::FtnIngressState::processing);check(!db.import_ftn_message(owner,direct.request),"owner resolution cannot bypass current direct admission policy");held_state(db,direct,app::FtnIngressState::held);
    check(db.shutdown().succeeded(),"fixture stopped");check(scalar(file,"SELECT count(*) FROM sfx_ftn_recipient_resolutions")==3,"all three decisions retained separately");check(scalar(file,"SELECT count(*) FROM sfx_local_messages WHERE author_account_id IS NULL")==1,"only one actual private delivery");check(scalar(file,"SELECT count(*) FROM sfx_ftn_ingress WHERE proof=0 AND state=3")==1,"direct receipt retains nonsecure held provenance");check(scalar(file,"SELECT count(*) FROM pragma_foreign_key_check")==0,"held and resolution references valid");
    {internal::SqliteConnection q(file,SQLITE_OPEN_READWRITE,std::chrono::milliseconds(100),false);bool refused=false;try{q.exec("UPDATE sfx_ftn_held_messages SET recipient='Alice'","fixture immutable ledger challenge");}catch(...){refused=true;}check(refused,"database trigger prevents remote To rewrite");refused=false;try{q.exec("DELETE FROM sfx_ftn_recipient_resolutions","fixture immutable resolution challenge");}catch(...){refused=true;}check(refused,"database trigger retains resolution history");}
    check(db.start().succeeded()&&db.held_ftn_messages(owner,{},10).value->size()==1,"restart retains only unresolved original");check(db.shutdown().succeeded(),"final shutdown");std::cout<<"PASS "<<checks<<" actual SQLite held-message checks (synthetic native custody/authentication)\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';return 1;}}
